  if (secureUser?.role === "parent") return <ParentWorkspace user={secureUser} onLogout={logoutSecure} />;
  if (secureUser?.role === "admin") return <AdminWorkspace user={secureUser} onLogout={logoutSecure} />;
  if (user?.role === "student") return <StudentWorkspace user={user} onLogout={() => setUser(null)} />;
  if (user?.role === "parent") return <ParentWorkspace user={user} onLogout={() => setUser(null)} />;
